CREATE OR REPLACE TABLE conductor_s_execution AS
WITH dept_cols AS (
  SELECT columns FROM departments
), has_dept_name AS (
  SELECT 1 AS ok FROM dept_cols WHERE lower(columns) = 'department_name' LIMIT 1
), phone_area AS (
  SELECT 1 AS ok FROM dept_cols WHERE lower(columns) = 'department_phone_area_code' LIMIT 1
), phone_num AS (
  SELECT 1 AS ok FROM dept_cols WHERE lower(columns) = 'department_phone_number' LIMIT 1
), stud_cols AS (
  SELECT columns FROM students
), has_student_dept AS (
  SELECT 1 AS ok FROM stud_cols WHERE lower(columns) = 'department_name' LIMIT 1
), has_full_name AS (
  SELECT 1 AS ok FROM stud_cols WHERE lower(columns) = 'full_name' LIMIT 1
)
SELECT 
  'No data: T contains only column-name listings, not actual fact rows' AS department_name,
  NULL AS department_phone_number,
  0 AS number_of_students,
  0 AS longest_full_name_length
WHERE NOT EXISTS (SELECT 1 FROM has_dept_name)
   OR NOT EXISTS (SELECT 1 FROM has_student_dept)
   OR NOT EXISTS (SELECT 1 FROM has_full_name);
